import React, { useEffect, useState } from "react";
import { FaBars, FaTimes } from "react-icons/fa";
import Nav from './component/nav';
import api from '../api';

const Pendaftar = () => {
  const [data, setData] = useState([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  
  const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  useEffect(() => {
    // Panggil API Laravel untuk mengambil data
    api.get('/mahasiswa')
      .then(response => {
        setData(response.data);
      })
      .catch(error => {
        console.error("Error fetching data:", error);
      });
  }, []);

  return (
    <div className="flex flex-col h-screen bg-teal-100 font-sans">
      {/* Header */}
      <header className="bg-teal-200 text-teal-800 px-6 py-4 flex justify-between items-center shadow">
        <div className="flex">
            <h1 className="text-4xl font-bold mr-10">Admin Panel</h1>
            <button onClick={toggleSidebar} className="text-3xl">
              {isSidebarOpen ? <FaTimes /> : <FaBars />}
            </button>
        </div>
        <div className="flex items-center">
          <span className="material-icons text-3xl mr-2">account_circle</span>
        </div>
      </header>

      {/* Container */}
      <div className="flex flex-1 overflow-hidden">
        {/* Sidebar */}
        <Nav isSidebarOpen={isSidebarOpen} />

        {/* Main Content */}
        <main className="flex-1 bg-teal-50 p-6 overflow-y-auto">
          <h2 className="text-2xl font-bold mb-4">Pendaftar</h2>
          <div className="overflow-x-auto">
          <form id="form" onSubmit={handleSubmit}>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="mb-4">
                <label htmlFor="nama" className="block text-teal-800 font-medium mb-2">Nama</label>
                <input
                  type="text"
                  id="nama"
                  value={formData.nama}
                  onChange={handleChange}
                  className="w-full p-3 border border-teal-300 rounded-lg"
                  required
                />
              </div>

              <div className="mb-4">
                <label htmlFor="nilai" className="block text-teal-800 font-medium mb-2">Nilai</label>
                <input
                  type="text"
                  id="nilai"
                  value={formData.nilai}
                  onChange={handleChange}
                  className="w-full p-3 border border-teal-300 rounded-lg"
                  required
                />
              </div>

              <div className="mb-4">
                <label htmlFor="alamat" className="block text-teal-800 font-medium mb-2">Alamat</label>
                <input
                  type="text"
                  id="alamat"
                  value={formData.alamat}
                  onChange={handleChange}
                  className="w-full p-3 border border-teal-300 rounded-lg"
                  required
                />
              </div>

              <div className="mb-4">
                <label htmlFor="tempat" className="block text-teal-800 font-medium mb-2">Tempat Lahir</label>
                <input
                  type="text"
                  id="tempat"
                  value={formData.tempat}
                  onChange={handleChange}
                  className="w-full p-3 border border-teal-300 rounded-lg"
                  required
                />
              </div>

              <div className="mb-4">
                <label htmlFor="lahir" className="block text-teal-800 font-medium mb-2">Tanggal Lahir</label>
                <input
                  type="date"
                  id="lahir"
                  value={formData.lahir}
                  onChange={handleChange}
                  className="w-full p-3 border border-teal-300 rounded-lg"
                  required
                />
              </div>

              <div className="mb-4">
                <label htmlFor="email" className="block text-teal-800 font-medium mb-2">Email</label>
                <input
                  type="email"
                  id="email"
                  value={formData.email}
                  onChange={handleChange}
                  className="w-full p-3 border border-teal-300 rounded-lg"
                  required
                />
              </div>

              <div className="mb-4">
                <label htmlFor="nisn" className="block text-teal-800 font-medium mb-2">NISN</label>
                <input
                  type="text"
                  id="nisn"
                  value={formData.nisn}
                  onChange={handleChange}
                  className="w-full p-3 border border-teal-300 rounded-lg"
                  required
                />
              </div>

              <div className="mb-4">
                <label htmlFor="no" className="block text-teal-800 font-medium mb-2">Nomor Telepon</label>
                <input
                  type="text"
                  id="no"
                  value={formData.no}
                  onChange={handleChange}
                  className="w-full p-3 border border-teal-300 rounded-lg"
                  required
                />
              </div>

              {/* Metode Pembayaran */}
              <div className="mb-4 col-span-2">
                <label htmlFor="metodePembayaran" className="block text-teal-800 font-medium mb-2">Metode Pembayaran</label>
                <select
                  id="metodePembayaran"
                  value={formData.metodePembayaran}
                  onChange={handleChange}
                  className="w-full p-3 border border-teal-300 rounded-lg"
                  required
                >
                  <option value="" disabled>Pilih metode pembayaran</option>
                  <option value="transfer_bank">Transfer Bank</option>
                  <option value="gopay">Gopay</option>
                  <option value="shopeepay">ShopeePay</option>
                  <option value="qris">QRIS</option>
                </select>
              </div>
            </div>

            <div className="text-center mt-6">
              <input
                type="submit"
                value="Kirim"
                className="w-full py-3 bg-teal-500 text-white rounded-lg cursor-pointer hover:bg-teal-600"
              />
            </div>
          </form>
          </div>
        </main>
      </div>
    </div>
  );
};

export default Pendaftar;
